-- HUFT Roster integration additions. Run after 001_initial_schema.sql.
create table if not exists public.roster_access_requests (id uuid primary key default gen_random_uuid(), requester_id uuid not null references public.profiles(id), requested_email text not null, store_name text not null, reason text, status public.request_status not null default 'pending', reviewer_id uuid references public.profiles(id), reviewer_notes text, created_at timestamptz not null default now(), reviewed_at timestamptz);
create table if not exists public.email_templates (id text primary key, name text not null, enabled boolean not null default false, subject text not null, body text not null, updated_by uuid references public.profiles(id), updated_at timestamptz not null default now());
create table if not exists public.email_delivery_logs (id uuid primary key default gen_random_uuid(), template_id text, reference_id text, recipient text not null, subject text, status text not null, attempts integer not null default 1, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.employees add column if not exists reports_to text;
alter table public.deployment_requests add column if not exists employee_name text;
alter table public.deployment_requests add column if not exists employee_code text;
alter table public.deployment_requests add column if not exists from_store_name text;
alter table public.deployment_requests add column if not exists to_store_name text;
alter table public.roster_access_requests enable row level security; alter table public.email_templates enable row level security; alter table public.email_delivery_logs enable row level security;
create or replace function public.can_view_employee(target_employee uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.employees e where e.id=target_employee and public.can_access_store(e.store_id,false)) or exists(select 1 from public.roster_entries r where r.employee_id=target_employee and r.deployment_store_id is not null and public.can_access_store(r.deployment_store_id,false)) $$;
create or replace function public.can_edit_roster_entry(target_employee uuid,target_deployment_store uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.employees e where e.id=target_employee and public.can_access_store(e.store_id,true)) or (target_deployment_store is not null and public.can_access_store(target_deployment_store,true)) $$;
drop policy if exists "employees view within permitted stores" on public.employees;
create policy "employees visible in home or deployment stores" on public.employees for select to authenticated using (public.can_view_employee(id));
drop policy if exists "roster visible within permitted stores" on public.roster_entries;
drop policy if exists "authorized managers edit roster" on public.roster_entries;
drop policy if exists "authorized managers update roster" on public.roster_entries;
drop policy if exists "authorized managers delete roster" on public.roster_entries;
create policy "roster visible in home or destination store" on public.roster_entries for select to authenticated using (public.can_view_employee(employee_id));
create policy "managers insert roster for home or deployment store" on public.roster_entries for insert to authenticated with check (public.can_edit_roster_entry(employee_id,deployment_store_id));
create policy "managers update roster for home or deployment store" on public.roster_entries for update to authenticated using (public.can_edit_roster_entry(employee_id,deployment_store_id)) with check (public.can_edit_roster_entry(employee_id,deployment_store_id));
create policy "managers delete roster for home or deployment store" on public.roster_entries for delete to authenticated using (public.can_edit_roster_entry(employee_id,deployment_store_id));
create policy "users create own access request" on public.roster_access_requests for insert to authenticated with check (requester_id=auth.uid());
create policy "requester or super admin read access requests" on public.roster_access_requests for select to authenticated using (requester_id=auth.uid() or public.current_app_role()='super_admin');
create policy "super admin review access requests" on public.roster_access_requests for update to authenticated using (public.current_app_role()='super_admin') with check (public.current_app_role()='super_admin');
create policy "super admin manages email templates" on public.email_templates for all to authenticated using (public.current_app_role()='super_admin') with check (public.current_app_role()='super_admin');
create policy "super admin reads email logs" on public.email_delivery_logs for select to authenticated using (public.current_app_role()='super_admin');
create policy "requester or store manager reads employee requests" on public.employee_requests for select to authenticated using (requester_id=auth.uid() or public.can_access_store(store_id,false));
create policy "employee creates own request" on public.employee_requests for insert to authenticated with check (requester_id=auth.uid());
create policy "managers review employee requests in assigned stores" on public.employee_requests for update to authenticated using (public.can_access_store(store_id,true)) with check (public.can_access_store(store_id,true));
create policy "requester or destination manager reads deployment requests" on public.deployment_requests for select to authenticated using (requester_id=auth.uid() or public.can_access_store(to_store_id,false));
create policy "home store manager creates deployment requests" on public.deployment_requests for insert to authenticated with check (requester_id=auth.uid() and public.can_access_store(from_store_id,true));
create policy "destination manager reviews deployments" on public.deployment_requests for update to authenticated using (public.can_access_store(to_store_id,true)) with check (public.can_access_store(to_store_id,true));
create policy "punctuality visible by store" on public.punctuality_events for select to authenticated using (exists(select 1 from public.employees e where e.id=employee_id and public.can_access_store(e.store_id,false)));
create policy "managers add punctuality" on public.punctuality_events for insert to authenticated with check (public.can_access_store((select store_id from public.employees where id=employee_id),true));
